#!/usr/bin/env bash
# profile.sh - run Nsight Compute on every kernel at N=2048 (override: N=1024 ./scripts/profile.sh)
#
# Output:  results/ncu/<kernel>.ncu-rep   (open in the Nsight Compute GUI)
#          results/ncu/<kernel>.log       (raw ncu console output)
#          results/ncu_summary.md         (generated by scripts/ncu_summary.py)
# Optional: FULL=1 also saves results/ncu/<kernel>_full.ncu-rep with `--set full`.
set -uo pipefail
cd "$(dirname "$0")/.."

BIN=build/sgemm_bench
N="${N:-2048}"
KERNELS=(naive coalesced smem_tiled reg_blocked vectorized)

command -v ncu >/dev/null || { echo "ncu not found. Install the CUDA Toolkit / Nsight Compute and add it to PATH."; exit 1; }
[ -x "$BIN" ] || { echo "$BIN not found. Run 'make build' first."; exit 1; }

# Raw hardware counters we need (see scripts/ncu_summary.py for how they are used).
METRICS=(
  gpu__time_duration.sum
  dram__throughput.avg.pct_of_peak_sustained_elapsed
  lts__throughput.avg.pct_of_peak_sustained_elapsed
  sm__warps_active.avg.pct_of_peak_sustained_active
  launch__registers_per_thread
  l1tex__data_bank_conflicts_pipe_lsu_mem_shared_op_ld.sum
  l1tex__data_bank_conflicts_pipe_lsu_mem_shared_op_st.sum
  "regex:smsp__average_warps_issue_stalled_.*_per_issue_active\.ratio"
)
METRIC_ARG=$(IFS=,; echo "${METRICS[*]}")

print_perm_fix() {
cat <<'MSG'

================================================================================
ncu failed with ERR_NVGPUCTRPERM: the driver blocks GPU performance counters for
non-admin users. Fix for YOUR OS:

WINDOWS (native):
  1. Right-click the desktop -> NVIDIA Control Panel
     (menu: Desktop -> "Enable Developer Settings" if not already ticked).
  2. Developer -> Manage GPU Performance Counters
  3. Select "Allow access to the GPU performance counters to all users"
     (needs an administrator prompt), then re-run this script.
  Alternative: run this script from an *Administrator* terminal.

WSL2 (Ubuntu on Windows):
  Do the Windows steps above (the setting is controlled by the Windows driver;
  use an up-to-date NVIDIA Windows driver), then run `wsl --shutdown` and reopen WSL.

LINUX:
  Quickest: run with sudo:     sudo -E env "PATH=$PATH" bash scripts/profile.sh
  Permanent (until driver update): create /etc/modprobe.d/nvidia-prof.conf containing
        options nvidia NVreg_RestrictProfilingToAdminUsers=0
     then:   sudo update-initramfs -u     (Debian/Ubuntu)   or   sudo dracut -f   (Fedora/RHEL)
     and reboot. Verify with:  cat /proc/driver/nvidia/params | grep RestrictProfiling
     (should show 0).
================================================================================
MSG
}

mkdir -p results/ncu
for k in "${KERNELS[@]}"; do
  echo "=== profiling $k @ N=$N ==="
  ncu --force-overwrite --export "results/ncu/$k" \
      --metrics "$METRIC_ARG" -k "regex:sgemm_" -c 1 \
      "$BIN" --kernel "$k" --sizes "$N" --profile > "results/ncu/$k.log" 2>&1
  rc=$?
  if [ $rc -ne 0 ]; then
    if grep -q "ERR_NVGPUCTRPERM" "results/ncu/$k.log"; then print_perm_fix; else tail -20 "results/ncu/$k.log"; fi
    echo "ncu failed for $k (exit $rc); see results/ncu/$k.log"
    exit $rc
  fi
  if [ "${FULL:-0}" = "1" ]; then
    ncu --force-overwrite --export "results/ncu/${k}_full" --set full -k "regex:sgemm_" -c 1 \
        "$BIN" --kernel "$k" --sizes "$N" --profile > "results/ncu/${k}_full.log" 2>&1 || true
  fi
done

python3 scripts/ncu_summary.py --n "$N"
echo "Wrote results/ncu_summary.md"
